    settings.configure(
        DATABASES={
            'default': {
                'ENGINE': 'django.db.backends.sqlite3',
                'NAME': ':memory:',
            }
        },
        INSTALLED_APPS=[
            'repro',
        ],
    )
    django.setup()

# Create a simple app for reproduction
class MyModel(models.Model):
    name = models.CharField(max_length=100)
    value = models.IntegerField()

    class Meta:
        app_label = 'repro'
        ordering = ['name']

# Create the table in the database
